-- release tested units into storage --------------------------------------
-- One UPDATE … JOIN instead of thousands of calls: the triggers still check
-- tests, consent, capacity and the status transition for every row.
DROP TABLE IF EXISTS _release_plan;
CREATE TABLE _release_plan (sample_id INT UNSIGNED PRIMARY KEY, location_id INT UNSIGNED, position VARCHAR(20)) ENGINE=InnoDB;
UPDATE stem_cell_sample s
  JOIN _release_plan p ON p.sample_id = s.sample_id
   SET s.processing_status   = 'RELEASED',
       s.location_id         = p.location_id,
       s.storage_position    = p.position,
       s.availability_status = 'AVAILABLE';

-- units already past their expiry: stored, but never offered
DELETE FROM _release_plan;
UPDATE stem_cell_sample s
  JOIN _release_plan p ON p.sample_id = s.sample_id
   SET s.processing_status = 'RELEASED',
       s.location_id       = p.location_id,
       s.storage_position  = p.position;
DROP TABLE _release_plan;

