UPDATE storage_location SET current_status = 'MAINTENANCE' WHERE location_id = 18;
UPDATE storage_location SET current_status = 'MAINTENANCE' WHERE location_id = 31;
UPDATE storage_location SET current_status = 'DECOMMISSIONED' WHERE location_id = 47;
UPDATE hospital SET status = 'SUSPENDED' WHERE hospital_id = 13;
UPDATE hospital SET status = 'INACTIVE' WHERE hospital_id = 24;
UPDATE doctor SET status = 'ON_LEAVE' WHERE doctor_id IN (7, 19);
UPDATE doctor SET status = 'INACTIVE' WHERE doctor_id IN (13, 25);
UPDATE `user` SET status = 'INACTIVE' WHERE username IN ('staff.farhan');
UPDATE `user` SET status = 'LOCKED' WHERE username IN ('dr.tejas');
UPDATE donor SET status = 'DEFERRED' WHERE donor_id IN (336, 343, 350, 411, 438, 445, 466, 485, 502, 532, 561, 575, 608, 710, 711, 712, 745, 747, 752, 800, 890, 894, 924, 926, 1005, 1062, 1116, 1129, 1187, 1193, 1213, 1217, 1232, 1255, 1271, 1291, 1298, 1306, 1330, 1336, 1352, 1365, 1388, 1396, 1493, 1526, 1531, 1536, 1537, 1555, 1596);
